import { test, expect } from '@playwright/test';

test.describe('Search Term Highlighting in Result Snippets', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should highlight search terms in result snippets', async ({ page }) => {
    // Set up search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('playwright automation');

    // Set up search button using getByRole
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for search results to load
    await page.waitForSelector('[data-testid="search-results"]');

    // Verify search results are visible
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();

    // Verify search term is highlighted in the first result snippet
    const firstResultSnippet = page.getByTestId('result-snippet-1');
    await expect(firstResultSnippet).toContainText('playwright automation');

    // Verify highlighting is applied using getByRole
    const highlightedTerm = page.getByRole('heading', { name: /playwright automation/i });
    await expect(highlightedTerm).toBeVisible();

    // Verify highlighted term is styled differently
    await expect(highlightedTerm).toHaveClass(/highlighted-term/);

    // Verify search term is highlighted in the second result snippet
    const secondResultSnippet = page.getByTestId('result-snippet-2');
    await expect(secondResultSnippet).toContainText('playwright automation');

    // Verify highlighting is applied using getByRole
    const secondHighlightedTerm = page.getByRole('heading', { name: /playwright automation/i });
    await expect(secondHighlightedTerm).toBeVisible();

    // Verify highlighted term is styled differently
    await expect(secondHighlightedTerm).toHaveClass(/highlighted-term/);

    // Verify search term is not highlighted in a non-result snippet
    const nonResultSnippet = page.getByTestId('non-result-snippet');
    await expect(nonResultSnippet).not.toContainText('playwright automation');

    // Verify search term is highlighted in the last result snippet
    const lastResultSnippet = page.getByTestId('result-snippet-last');
    await expect(lastResultSnippet).toContainText('playwright automation');

    // Verify highlighted term is styled differently
    const lastHighlightedTerm = page.getByRole('heading', { name: /playwright automation/i });
    await expect(lastHighlightedTerm).toHaveClass(/highlighted-term/);
  });

  test('should handle search term with special characters and spaces', async ({ page }) => {
    // Set up search input using getByLabel
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('playwright automation with spaces & special chars');

    // Set up search button using getByRole
    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Wait for search results to load
    await page.waitForSelector('[data-testid="search-results"]');

    // Verify search results are visible
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();

    // Verify search term is highlighted in the first result snippet
    const firstResultSnippet = page.getByTestId('result-snippet-1');
    await expect(firstResultSnippet).toContainText('playwright automation with spaces & special chars');

    // Verify highlighted term is styled differently
    const firstHighlightedTerm = page.getByRole('heading', { name: /playwright automation with spaces & special chars/i });
    await expect(firstHighlightedTerm).toHaveClass(/highlighted-term/);

    // Verify search term is highlighted in the second result snippet
    const secondResultSnippet = page.getByTestId('result-snippet-2');
    await expect(secondResultSnippet).toContainText('playwright automation with spaces & special chars');

    // Verify highlighted term is styled differently
    const secondHighlightedTerm = page.getByRole('heading', { name: /playwright automation with spaces & special chars/i });
    await expect(secondHighlightedTerm).toHaveClass(/highlighted-term/);

    // Verify search term is not highlighted in a non-result snippet
    const nonResultSnippet = page.getByTestId('non-result-snippet');
    await expect(nonResultSnippet).not.toContainText('playwright automation with spaces & special chars');

    // Verify search term is highlighted in the last result snippet
    const lastResultSnippet = page.getByTestId('result-snippet-last');
    await expect(lastResultSnippet).toContainText('playwright automation with spaces & special chars');

    // Verify highlighted term is styled differently
    const lastHighlightedTerm = page.getByRole('heading', { name: /playwright automation with spaces & special chars/i });
    await expect(lastHighlightedTerm).toHaveClass(/highlighted-term/);
  });
});
